        parent = self.parent
        fullname = self._name
        while isinstance(parent, _CompositeCommand):
            if parent.name:
                fullname = parent.name + ' ' + fullname
            parent = parent.parent
        return fullname

    @property
    def usage(self):
        return self.parser.format_usage().rstrip()

