class BaseModel(db.Model):
    __abstract__ = True

    @staticmethod
    def create(new_entry, commit=True):
        try:
            db.session.add(new_entry)
            if commit:
                db.session.commit()
            return new_entry.id
        except Exception as e:
            print("c", e)
            return False

    @classmethod
    def read(cls, id_) -> Callable[..., "BaseModel"]:
        return BaseModel.query.get(id_)

    def update(self, commit=True):
        try:
            if commit:
                db.session.commit()
            return self.id
        except Exception as e:
