""" Simple rclone interface """

import os
import logging
import json
import subprocess
import tempfile
import re

from .util import parse_rfc3339

class RClone(object):
    """ Wrapper class around the rclone executable """
    def __new__(cls, *args, **kwds):
        singleton = cls.__dict__.get("__it__")
        if singleton is not None:
            return singleton
        cls.__it__ = singleton = object.__new__(cls)
        singleton.setup(*args, **kwds)
        return singleton

    def setup(self, rclone_path="", rclone_executable="rclone"):
        """ Setup the rclone path and executable """
        if not rclone_path:
            self.rclone_file = rclone_executable
        else:
            self.rclone_file = os.path.join(rclone_path, rclone_executable)
        self.harmonize_timestamp_precision = True #TODO: set this depending on rclone version

    def backup_operation(self, args, no_backup=False, remote_backup=None, remote_suffix=None):
        """ Backup-aware operation """
        if not no_backup:
            if remote_backup:
                args += ["--backup-dir", remote_backup]
                if remote_suffix:
                    args += ["--suffix", remote_suffix]
        return self.run(args)

    def mkdir(self, path):
        """ mkdir """
        args = ["mkdir", path]
        return self.run(args)

    def delete(self, path, no_backup=False, remote_backup=None, remote_suffix=None):
        """ delete """
        args = ["delete", path]
        return self.backup_operation(args, no_backup, remote_backup, remote_suffix)

    def purge(self, path, no_backup=False, remote_backup=None, remote_suffix=None):
        """ purge: delete a path and its contents """
        args = ["purge", path]
        return self.backup_operation(args, no_backup, remote_backup, remote_suffix)

    def copy(self, source, dest, no_backup=False, remote_backup=None, remote_suffix=None):
        """ copy """
        args = ["copyto", source, dest]
        return self.backup_operation(args, no_backup, remote_backup, remote_suffix)

    def move(self, source, dest, no_backup=False, remote_backup=None, remote_suffix=None):
        """ move """
        args = ["moveto", source, dest]
        return self.backup_operation(args, no_backup, remote_backup, remote_suffix)

    def sync(self, source, dest, no_backup=False, remote_backup=None, remote_suffix=None):
        """ sync: make destination the same as source """
        args = ["sync", source, dest]
        return self.backup_operation(args, no_backup, remote_backup, remote_suffix)

    def lsjson(self, path):
        args = ["lsjson", "-R", "--skip-links", path]
        output = self.run(args)
        if self.harmonize_timestamp_precision:
            top_precision = 0
            paths_list = json.loads(output)
            for path_json in paths_list:
                datetime = path_json["ModTime"]
                (_, time_precision) = parse_rfc3339(datetime, report_precision=True)
                if time_precision > top_precision:
                    top_precision = time_precision
            #now make all timestamps use the same number of decimal digits
            #TODO: use it only with older version of rclone
            def replacer(matchobj):
                time = matchobj.group(1)
                decimal = matchobj.group(2)
                if not decimal:
                    decimal = "."
                return time+(decimal+("0"*top_precision))[0:top_precision+1]
            for path_json in paths_list:
                path_json["ModTime"] = re.sub(r'(\d\d?:\d\d?:\d\d?)(\.\d+)?', replacer, path_json["ModTime"])
            return json.dumps(paths_list)
        else:
            return output

    def write_file(self, path, content):
        """ Writes content to a file. Operates by creating a tempfile and moving
            it with rclone
        """
        tmp_fp, tmp_filename = tempfile.mkstemp()
        os.write(tmp_fp, bytes(content, encoding='UTF-8'))
        os.close(tmp_fp)
        self.move(tmp_filename, path)

    def run(self, args):
        """ Invoke rclone with the given arguments """
        args = [self.rclone_file] + args
        logging.info("Running "+str(args))
        output = subprocess.check_output(args, stderr=subprocess.STDOUT, encoding='UTF-8')
        logging.log(logging.INFO-1, "Output: "+output)
        return output

import inspect

from rest_framework.settings import api_settings


class PolymorphicProxySerializer:
    """
    This class is to be used with :func:`@extend_schema <.extend_schema>` to
    signal a request/response might be polymorphic (accepts/returns data
    possibly from different serializers)

    Beware that this is not a real serializer and therefore is not derived from
    serializers.Serializer. It *cannot* be used in views as `serializer_class`
    or as field in a actual serializer. You likely want to handle this in the
    view method.

    Also make sure that each sub-serializer has a field named after the value of
    `resource_type_field` (discriminator field) for the the mapping and parity
    with with the generated schema.
    """

    def __init__(self, component_name, serializers, resource_type_field_name):
        self.component_name = component_name
        self.serializers = serializers
        self.resource_type_field_name = resource_type_field_name


class OpenApiSchemaBase:
    pass


class OpenApiParameter(OpenApiSchemaBase):
    QUERY = 'query'
    PATH = 'path'
    HEADER = 'header'
    COOKIE = 'cookie'

    def __init__(self, name, type=str, location=QUERY, required=False, description='', enum=None, deprecated=False):
        self.name = name
        self.type = type
        self.location = location
        self.required = required
        self.description = description
        self.enum = enum
        self.deprecated = deprecated


def extend_schema(
        operation_id=None,
        parameters=None,
        request=None,
        responses=None,
        auth=None,
        description=None,
        deprecated=None,
        tags=None,
        exclude=False,
        operation=None,
        methods=None,
):
    """
    decorator for the "view" kind. partially or completely overrides what would be
    generated by drf-spectacular.

    :param operation_id: replaces the auto-generated operation_id. make sure there
        are no naming collisions.
    :param parameters: list of additional or replacement parameters added to the
        auto-discovered fields.
    :param responses: replaces the discovered Serializer. Takes a variety of
        inputs that can be used individually or combined

        - ``Serializer`` class
        - ``Serializer`` instance (e.g. ``Serializer(many=True)`` for listings)
        - ``dict`` with status codes as keys and `Serializers` as values.
        - :class:`.PolymorphicProxySerializer` for signaling that
          the operation may yield data from different serializers depending
          on the circumstances.
    :param request: replaces the discovered ``Serializer``.
    :param auth:
    :param description: replaces discovered doc strings
    :param deprecated: mark operation as deprecated
    :param tags: override default list of tags
    :param exclude: set True to exclude operation from schema
    :param operation: manually override what auto-discovery would generate. you must
        provide a OpenAPI3-compliant dictionary that gets directly translated to YAML.
    :param methods: scope extend_schema to specific methods. matches all by default.
    :return:
    """
    def decorator(f):
        BaseSchema = (
            getattr(f, 'schema', None)
            or getattr(f, 'kwargs', {}).get('schema', None)
            or api_settings.DEFAULT_SCHEMA_CLASS
        )
        if not inspect.isclass(BaseSchema):
            BaseSchema = BaseSchema.__class__

        def method_matches(method):
            return methods is None or method in methods

        class ExtendedSchema(BaseSchema):
            def get_operation(self, path, method, registry):
                if method_matches(method) and exclude:
                    return None
                if method_matches(method) and operation is not None:
                    return operation
                return super().get_operation(path, method, registry)

            def get_operation_id(self):
                if method_matches(self.method) and operation_id:
                    return operation_id
                return super().get_operation_id()

            def get_override_parameters(self):
                if method_matches(self.method) and parameters:
                    return parameters
                return super().get_override_parameters()

            def get_auth(self):
                if method_matches(self.method) and auth:
                    return auth
                return super().get_auth()

            def get_request_serializer(self):
                if method_matches(self.method) and request:
                    return request
                return super().get_request_serializer()

            def get_response_serializers(self):
                if method_matches(self.method) and responses:
                    return responses
                return super().get_response_serializers()

            def get_description(self):
                if method_matches(self.method) and description:
                    return description
                return super().get_description()

            def is_deprecated(self):
                if method_matches(self.method) and deprecated:
                    return deprecated
                return super().is_deprecated()

            def get_tags(self):
                if method_matches(self.method) and tags is not None:
                    return tags
                return super().get_tags()

        if inspect.isclass(f):
            class ExtendedView(f):
                schema = ExtendedSchema()

            return ExtendedView
        elif callable(f):
            # custom actions have kwargs in their context, others don't. create it so our create_view
            # implementation can overwrite the default schema
            if not hasattr(f, 'kwargs'):
                f.kwargs = {}
            # this simulates what @action is actually doing. somewhere along the line in this process
            # the schema is picked up from kwargs and used. it's involved my dear friends.
            # use class instead of instance due to descriptor weakref reverse collisions
            f.kwargs['schema'] = ExtendedSchema
            return f
        else:
            return f

    return decorator


def extend_schema_field(field):
    """
    Decorator for the "field" kind. Can be used with ``SerializerMethodField`` (annotate the actual
    method) or with custom ``serializers.Field`` implementations.

    If your custom serializer field base class is already the desired type, decoration is not necessary.
    To override the discovered base class type, you can decorate your custom field class.

    Always takes precedence over other mechanisms (e.g. type hints, auto-discovery).

    :param field: accepts a ``Serializer`` or :class:`~.types.OpenApiTypes`
    """

    def decorator(f):
        f._spectacular_annotation = field
        return f

    return decorator

