        if len(vaza.saco)==0:
            return self.calcula_menor_carta(cartas)
        else:
            for carta in cartas:
                for carta_outro_jogador in vaza.saco:
                    if carta['valor']>=melhor_carta['valor'] and carta['valor']<carta_outro_jogador['valor']:
