        melhor_naipe=None
        melhor_min=200
        melhor_puxada=None

        probabilidade_ganho_por_naipe=self.calcula_prob_de_victoria_por_naipe(cartas,cartas_que_ainda_nao_sairam)

        for idx,c in enumerate(probabilidade_ganho_por_naipe):
            if c<melhor_min:
