    for i in sql.split():
        for c in BLACKLIST:
            if i == c:
                return True

def sql_as_ex(sql, sensitive_list):
    count = 0
    sql = sql.split(',')
    complete = []
    for comma in sql:
        _a = comma.split(' ')
        for _i in _a:
            if _i is not '':
                complete.append(_i)
    for gen in complete:
        if gen == 'as':
            count += 1
    if count != 0:
        as_list = []
        for i in range(len(complete)):
            if complete[i] == 'as':
                for s in sensitive_list:
                    if complete[i - 1] == s:
                        as_list.append(complete[i + 1].rstrip(','))

        if as_list is not None:
            for sen_i in as_list:
                sensitive_list.append(sen_i)
        return sensitive_list
    else:
        return sensitive_list

