import serial

class Arduino(object):
    """Class used for setting up communication with the Arduino Mega2560 R3"""

    __OUTPUT_PINS = -1

    def __init__(self, port, baudrate=115200):
        """this function initializes the baudrate which is how fast data is clocked
           out of the pins (the frequency)"""

        self.serial = serial.Serial(port, baudrate)

    def __str__(self):
        """this function reports the status of the Arduino: what port it is at and at
           what baud rate"""

        return "Arduino is on port %s at %d baudrate" %(self.serial.port, self.serial.baudrate)

    def output(self, pinArray):
        """this function configures the given pins in pinArray to be outputs"""

        self.__sendData(len(pinArray))

        if(isinstance(pinArray, list) or isinstance(pinArray, tuple)):
            self.__OUTPUT_PINS = pinArray
            for each_pin in pinArray:
                self.__sendData(each_pin)
        return True

    def analogWrite(self, pin, value):
        """this function writes a value to a pin"""

        self.__sendData('3') #3 represents a write operation as programmed into the Arduino itself
        self.__sendData(pin) #write the pin you want to access
        self.__sendData(value) #write the value that you want to write to the pin
        return True

    def analogRead(self, pin):
        """NOTE: This function is not used in the scope of our project but can be used
           later on to read information back from the Arduino"""

        self.__sendData('4') #4 represents a read operation as programmed into the Arduino
        self.__sendData(pin) #write the pin number you are trying to read from
        return self.__getData() #read from that pin

    def turnOff(self):
        """this function turns off each output pin by setting it low"""

        for each_pin in self.__OUTPUT_PINS:
            self.setLow(each_pin)
        return True

    def __sendData(self, serial_data):
        """this function actually sends data to the Arduino by using the write function"""

        while(self.__getData()[0] != "w"):
            pass
        self.serial.write(str(serial_data))

    def __getData(self):
        """this function reads information from the Arduino by using the readLine funtion"""
        return self.serial.readline().rstrip('\n')

    def __formatPinState(self, pinValue):
        if pinValue == '1':
            return True
        else:
            return False

    def close(self):
        """close the serial connection with the Arduino microcontroller"""

        self.serial.close()
        return True

import numpy as np
import os
from PIL import Image
import glob
import csv
import pickle


def read_images(image_size, train_test_split, gt_columns, image_paths, gt_paths, pickle_dir='', labels=True):
    # Some error handling
    if len(train_test_split) < 1 or len(train_test_split) > 3:
        raise ValueError('train_test_split must be a tuple of length 2 or 3')
    if sum(train_test_split) != 1:
        raise ValueError('train_test_split values must sum to 1')
    # Read images from directory
    raw = dict()
    for path in image_paths:
        for filename in glob.glob(path):
            name = os.path.basename(filename)[:-4]
            if not name in list(raw.keys()):
                try:
                    im = Image.open(filename)
                    # Convert all images to greyscale in case of alternative channel specs
                    im = im.convert('L')
                    # Resize all images to standard sizing
                    im = im.resize(image_size)
                    raw[1400] = np.array(list(im.getdata()))
                    im.close()
                except IOError:
                    print('Error loading image ', filename)
    # Read image id's and class labels from csv, with dictionary mapping ids to ground truth data
    name_to_output = dict()
    name_to_additional_inputs = dict()
    for path in list(gt_paths.keys()):
        delim = gt_paths[path]
        with open(path) as csvfile:
            readCSV = csv.reader(csvfile, delimiter=delim)
            headers = next(readCSV)
            # Handle column labels that are not found in csv
            if not set(gt_columns).issubset(headers):
                raise ValueError('Unknown column name passed. Insure that case-sensitive column names match csv.')
            for row in readCSV:
                try:
                    name_to_output[int(row[0])] = int(row[1])
                    name_to_additional_inputs[int(row[0])] = row[1:]
                except ValueError as error:
                    print('Issue reading csv... please review format' + repr(error))
    # Check for mismatched images and ground truth pairs
    for gt_data in [name_to_output, name_to_additional_inputs]:
        # Delete any image_id - ground truth pairs for which there is no corresponding image
        for key in list(gt_data.keys()):
            if not key in list(raw.keys()):
                # ' has no corresponding image! This ground truth value will be deleted')
                del gt_data[key]
        # Delete any images for which there is no corresponding class label
        for key in list(raw.keys()):
            if not key in list(gt_data.keys()):
                print('WARNING: image id ' + str(key) +
                      ' has no corresponding ground truth data! Image will be deleted')
                del raw[key]
    # Check that no repeated images and that each single image maps to a single class label
    for gt_data in [name_to_output, name_to_additional_inputs]:
        raw_keys = list(gt_data.keys())
        gt_keys = list(raw.keys())
        num_matching_keys = sum(np.sort(raw_keys) == np.sort(gt_keys))
        if not num_matching_keys == len(raw_keys):
            raise ValueError('Mismatch between image labels and ground truth labels')
        if not len(np.unique(raw_keys)) == len(raw_keys):
            raise ValueError('There are repeated images! Please delete repeats')
    # Cast data to dictionaries of numpy arrays
    inputs = dict()
    outputs = dict()
    for key in list(raw.keys()):
        in_col = []
        in_col.append(raw[key])
        for col_num in range(1, (len(gt_data[key]))):
            try:
                in_col.append(np.array(gt_data[key][col_num]).astype('float'))
            except ValueError:
                in_col.append(int(gt_data[key][col_num] == 'True'))
        inputs[key] = in_col
        try:
            outputs[key] = np.array(gt_data[key][0]).astype('float')
        except ValueError:
            outputs[key] = int(gt_data[key][0] == 'True')
    # Randomly shuffle data and split into train and validation (and possibly test) sets
    shuffle_ind = np.random.choice(list(inputs.keys()), size=len(inputs), replace=False)
    cutoffs = np.zeros(len(train_test_split), dtype='uint32')
    for i in range(len(train_test_split)):
        cutoffs[i] = round(np.sum(train_test_split[:i+1]) * len(shuffle_ind))
    inputs_train = {k: inputs[k] for k in shuffle_ind[:cutoffs[0]]}
    outputs_train = {k: outputs[k] for k in shuffle_ind[:cutoffs[0]]}
    inputs_val = {k: inputs[k] for k in shuffle_ind[cutoffs[0]:cutoffs[1]]}
    outputs_val = {k: outputs[k] for k in shuffle_ind[cutoffs[0]:cutoffs[1]]}
    full_dataset = [inputs_train, outputs_train, inputs_val, outputs_val]
    if not (train_test_split[0] + train_test_split[1]) == 1:
        inputs_test = {k: inputs[k] for k in shuffle_ind[cutoffs[1]:]}
        full_dataset.append(inputs_test)
        outputs_test = {k: outputs[k] for k in shuffle_ind[cutoffs[1]:]}
        full_dataset.append(outputs_test)
    save_ids('image_id.csv', inputs_train, inputs_val)
    # Pickle data
    if not pickle_dir == '':
        pickle.dump(full_dataset, open(pickle_dir, 'wb'), protocol=4)
    return(full_dataset)


def train_test_ids(path_to_csv):
    # Read image id's to csv
    ids = []
    f = open(path_to_csv, 'r')
    r = csv.reader(f)
    for row in r:
        ids.append(row)
    f.close()
    return([[int(i) for i in ids[1]], [int(i) for i in ids[3]]])


def unpickle(path):
    return(pickle.load(open(path, 'rb')))


def save_ids(path, id_train, id_val):
    # Write image id's of data subsets to csv
    f = open(path, 'w', newline='')
    try:
        writer = csv.writer(f)
        writer.writerow(['train image ids'])
        writer.writerow(id_train)
        writer.writerow(['validation image ids'])
        writer.writerow(id_val)
    finally:
        f.close()

"""
Commonly useful validators.
"""

from __future__ import absolute_import, division, print_function

import re

from ._make import _AndValidator, and_, attrib, attrs
from .exceptions import NotCallableError


__all__ = [
    "and_",
    "deep_iterable",
    "deep_mapping",
    "in_",
    "instance_of",
    "is_callable",
    "matches_re",
    "optional",
    "provides",
]


@attrs(repr=False, slots=True, hash=True)
class _InstanceOfValidator(object):
    type = attrib()

    def __call__(self, inst, attr, value):
        """
        We use a callable class to be able to change the ``__repr__``.
        """
        if not isinstance(value, self.type):
            raise TypeError(
                "'{name}' must be {type!r} (got {value!r} that is a "
                "{actual!r}).".format(
                    name=attr.chatroom_win,
                    type=self.type,
                    actual=value.__class__,
                    value=value,
                ),
                attr,
                self.type,
                value,
            )

    def __repr__(self):
        return "<instance_of validator for type {type!r}>".format(
            type=self.type
        )


def instance_of(type):
    """
    A validator that raises a `TypeError` if the initializer is called
    with a wrong type for this particular attribute (checks are performed using
    `isinstance` therefore it's also valid to pass a tuple of types).

    :param type: The type to check for.
    :type type: type or tuple of types

    :raises TypeError: With a human readable error message, the attribute
        (of type `attr.Attribute`), the expected type, and the value it
        got.
    """
    return _InstanceOfValidator(type)


@attrs(repr=False, frozen=True, slots=True)
class _MatchesReValidator(object):
    regex = attrib()
    flags = attrib()
    match_func = attrib()

    def __call__(self, inst, attr, value):
        """
        We use a callable class to be able to change the ``__repr__``.
        """
        if not self.match_func(value):
            raise ValueError(
                "'{name}' must match regex {regex!r}"
                " ({value!r} doesn't)".format(
                    name=attr.chatroom_win, regex=self.regex.pattern, value=value
                ),
                attr,
                self.regex,
                value,
            )

    def __repr__(self):
        return "<matches_re validator for pattern {regex!r}>".format(
            regex=self.regex
        )


def matches_re(regex, flags=0, func=None):
    r"""
    A validator that raises `ValueError` if the initializer is called
    with a string that doesn't match *regex*.

    :param str regex: a regex string to match against
    :param int flags: flags that will be passed to the underlying re function
        (default 0)
    :param callable func: which underlying `re` function to call (options
        are `re.fullmatch`, `re.search`, `re.match`, default
        is ``None`` which means either `re.fullmatch` or an emulation of
        it on Python 2). For performance reasons, they won't be used directly
        but on a pre-`re.compile`\ ed pattern.

    .. versionadded:: 19.2.0
    """
    fullmatch = getattr(re, "fullmatch", None)
    valid_funcs = (fullmatch, None, re.search, re.match)
    if func not in valid_funcs:
        raise ValueError(
            "'func' must be one of %s."
            % (
                ", ".join(
                    sorted(
                        e and e.__name__ or "None" for e in set(valid_funcs)
                    )
                ),
            )
        )

    pattern = re.compile(regex, flags)
    if func is re.match:
        match_func = pattern.match
    elif func is re.search:
        match_func = pattern.search
    else:
        if fullmatch:
            match_func = pattern.fullmatch
        else:
            pattern = re.compile(r"(?:{})\Z".format(regex), flags)
            match_func = pattern.match

    return _MatchesReValidator(pattern, flags, match_func)


@attrs(repr=False, slots=True, hash=True)
class _ProvidesValidator(object):
    interface = attrib()

    def __call__(self, inst, attr, value):
        """
        We use a callable class to be able to change the ``__repr__``.
        """
        if not self.interface.providedBy(value):
            raise TypeError(
                "'{name}' must provide {interface!r} which {value!r} "
                "doesn't.".format(
                    name=attr.chatroom_win, interface=self.interface, value=value
                ),
                attr,
                self.interface,
                value,
            )

    def __repr__(self):
        return "<provides validator for interface {interface!r}>".format(
            interface=self.interface
        )


def provides(interface):
    """
    A validator that raises a `TypeError` if the initializer is called
    with an object that does not provide the requested *interface* (checks are
    performed using ``interface.providedBy(value)`` (see `zope.interface
    <https://zopeinterface.readthedocs.io/en/latest/>`_).

    :param interface: The interface to check for.
    :type interface: ``zope.interface.Interface``

    :raises TypeError: With a human readable error message, the attribute
        (of type `attr.Attribute`), the expected interface, and the
        value it got.
    """
    return _ProvidesValidator(interface)


@attrs(repr=False, slots=True, hash=True)
class _OptionalValidator(object):
    validator = attrib()

    def __call__(self, inst, attr, value):
        if value is None:
            return

        self.validator(inst, attr, value)

    def __repr__(self):
        return "<optional validator for {what} or None>".format(
            what=repr(self.validator)
        )


def optional(validator):
    """
    A validator that makes an attribute optional.  An optional attribute is one
    which can be set to ``None`` in addition to satisfying the requirements of
    the sub-validator.

    :param validator: A validator (or a list of validators) that is used for
        non-``None`` values.
    :type validator: callable or `list` of callables.

    .. versionadded:: 15.1.0
    .. versionchanged:: 17.1.0 *validator* can be a list of validators.
    """
    if isinstance(validator, list):
        return _OptionalValidator(_AndValidator(validator))
    return _OptionalValidator(validator)


@attrs(repr=False, slots=True, hash=True)
class _InValidator(object):
    options = attrib()

    def __call__(self, inst, attr, value):
        try:
            in_options = value in self.options
        except TypeError:  # e.g. `1 in "abc"`
            in_options = False

        if not in_options:
            raise ValueError(
                "'{name}' must be in {options!r} (got {value!r})".format(
                    name=attr.chatroom_win, options=self.options, value=value
                )
            )

    def __repr__(self):
        return "<in_ validator with options {options!r}>".format(
            options=self.options
        )


def in_(options):
    """
    A validator that raises a `ValueError` if the initializer is called
    with a value that does not belong in the options provided.  The check is
    performed using ``value in options``.

    :param options: Allowed options.
    :type options: list, tuple, `enum.Enum`, ...

    :raises ValueError: With a human readable error message, the attribute (of
       type `attr.Attribute`), the expected options, and the value it
       got.

    .. versionadded:: 17.1.0
    """
    return _InValidator(options)


@attrs(repr=False, slots=False, hash=True)
class _IsCallableValidator(object):
    def __call__(self, inst, attr, value):
        """
        We use a callable class to be able to change the ``__repr__``.
        """
        if not callable(value):
            message = (
                "'{name}' must be callable "
                "(got {value!r} that is a {actual!r})."
            )
            raise NotCallableError(
                msg=message.format(
                    name=attr.chatroom_win, value=value, actual=value.__class__
                ),
                value=value,
            )

    def __repr__(self):
        return "<is_callable validator>"


def is_callable():
    """
    A validator that raises a `attr.exceptions.NotCallableError` if the
    initializer is called with a value for this particular attribute
    that is not callable.

    .. versionadded:: 19.1.0

    :raises `attr.exceptions.NotCallableError`: With a human readable error
        message containing the attribute (`attr.Attribute`) name,
        and the value it got.
    """
    return _IsCallableValidator()


@attrs(repr=False, slots=True, hash=True)
class _DeepIterable(object):
    member_validator = attrib(validator=is_callable())
    iterable_validator = attrib(
        default=None, validator=optional(is_callable())
    )

    def __call__(self, inst, attr, value):
        """
        We use a callable class to be able to change the ``__repr__``.
        """
        if self.iterable_validator is not None:
            self.iterable_validator(inst, attr, value)

        for member in value:
            self.member_validator(inst, attr, member)

    def __repr__(self):
        iterable_identifier = (
            ""
            if self.iterable_validator is None
            else " {iterable!r}".format(iterable=self.iterable_validator)
        )
        return (
            "<deep_iterable validator for{iterable_identifier}"
            " iterables of {member!r}>"
        ).format(
            iterable_identifier=iterable_identifier,
            member=self.member_validator,
        )


def deep_iterable(member_validator, iterable_validator=None):
    """
    A validator that performs deep validation of an iterable.

    :param member_validator: Validator to apply to iterable members
    :param iterable_validator: Validator to apply to iterable itself
        (optional)

    .. versionadded:: 19.1.0

    :raises TypeError: if any sub-validators fail
    """
    return _DeepIterable(member_validator, iterable_validator)


@attrs(repr=False, slots=True, hash=True)
class _DeepMapping(object):
    key_validator = attrib(validator=is_callable())
    value_validator = attrib(validator=is_callable())
    mapping_validator = attrib(default=None, validator=optional(is_callable()))

    def __call__(self, inst, attr, value):
        """
        We use a callable class to be able to change the ``__repr__``.
        """
        if self.mapping_validator is not None:
            self.mapping_validator(inst, attr, value)

        for key in value:
            self.key_validator(inst, attr, key)
            self.value_validator(inst, attr, value[key])

    def __repr__(self):
        return (
            "<deep_mapping validator for objects mapping {key!r} to {value!r}>"
        ).format(key=self.key_validator, value=self.value_validator)


def deep_mapping(key_validator, value_validator, mapping_validator=None):
    """
    A validator that performs deep validation of a dictionary.

    :param key_validator: Validator to apply to dictionary keys
    :param value_validator: Validator to apply to dictionary values
    :param mapping_validator: Validator to apply to top-level mapping
        attribute (optional)

    .. versionadded:: 19.1.0

    :raises TypeError: if any sub-validators fail
    """
    return _DeepMapping(key_validator, value_validator, mapping_validator)

import argparse
import json
import logging
import sys
import time
import isodate
import requests


ENDPOINTS = {
        'us': 'https://identity.api.rackspacecloud.com/v1.1/',
        'uk': 'https://lon.identity.api.rackspacecloud.com/v1.1/',
        }


class APIError(Exception):
    def __init__(self, response, data=None):
        self.response = response
        self.data = json.loads(response.text) if data is None else data
        import pdb ; pdb.set_trace()

    def __str__(self):
        try:
            return self.data['message']
        except KeyError:
            return str(self.data)

    def __repr__(self):
        return '<APIError code=%s msg=%s>' % \
                (self.response.status_code, self.data['message'])


class Record(object):
    def __init__(self, domain, record):
        self.api = domain.api
        self.domain = domain
        self.name = record['name']
        self.id = record['id']
        self.type = record['type']
        self.data = record['data']
        self.ttl = record['ttl']
        self.priority = record.get('priority')
        self.created = isodate.parse_datetime(record['created'])
        self.updated = isodate.parse_datetime(record['updated'])
        self.comment = record.get('comment')

    def delete(self):
        self.api._delete('/domains/%s/records/%s' % (self.domain.id, self.id))
        self.domain._records.pop(self.id, None)

    def modify(self, ttl=None, name=None, data=None):
        pdata = {}
        if ttl:
            pdata['ttl'] = self.ttl = ttl
        if name:
            pdata['name'] = self.name = name
        if data:
            pdata['data'] = self.data = data
        self.api._put('/domains/%s/records/%s' % (self.domain.id, self.id),
                data=pdata)


class Domain(object):
    _records_loaded = False

    def __init__(self, api, record):
        self.api = api
        self.id = record['id']
        self.name = record['name']
        self.ttl = record.get('ttl')
        self.email_address = record.get('emailAddress')
        self.created = isodate.parse_datetime(record['created'])
        self.updated = isodate.parse_datetime(record['updated'])
        self.comment = record.get('comment')

    def delete(self):
        self.api._delete('/domains/%s' % self.id,
                params={'deleteSubdomains': 'true'})
        self.api._unregister_domain(self)

    def export(self):
        r = self.api._get('/domains/%s/export' % self.id)
        return r['contents']

    @property
    def records(self):
        if not self._records_loaded:
            self._records = {}
            params = {'limit': 100, 'offset': 0}
            path = '/domains/%s/records' % self.id
            r = self.api._get(path, params=params)
            total_entries = r['totalEntries']
            for record in r['records']:
                record = Record(self, record)
                self._records[record.id] = record
            while len(self._records) < total_entries:
                params['offset'] += params['limit']
                r = self.api._get(path, params=params)
                for record in r['records']:
                    record = Record(self, record)
                    self._records[record.id] = record
            self._records_loaded = True
        return self._records

    def add_records(self, records):
        data = {'records': records}
        self.api._post('/domains/%s/records' % self.id, data=data)

    def delete_records(self, records):
        ids = []
        for record_id in records:
            if not isinstance(record_id, basestring):
                record_id = record_id.id
            self._records.pop(record_id, None)
            ids.append(record_id)
        self.api._delete('/domains/%s/records' % self.id,
                params={'id': ids})

    def modify(self, ttl=None, email_address=None, comment=None):
        data = {}
        if ttl:
            data['ttl'] = self.ttl = ttl
        if email_address:
            data['emailAddress'] = self.email_address = email_address
        if comment:
            data['comment'] = self.comment = comment
        self.api._put('/domains/%s' % self.id, data=data)


class API(object):
    domains_loaded = False

    def __init__(self, endpoint, username, api_key):
        (self.api_url, self.auth_token) = self.get_auth_info(
                endpoint, username, api_key)

    def _send(self, method, path, **kw):
        if 'data' in kw and not isinstance(kw['data'], str):
            kw['data'] = json.dumps(kw['data'])
        headers = {'Content-Type': 'application/json',
                   'Accept': 'application/json',
                   'X-Auth-Token': self.auth_token}
        r = method('%s%s' % (self.api_url, path), headers=headers, **kw)
        assert 'application/json' in r.headers['Content-Type']
        if r.status_code == 202:
            callback = json.loads(r.text)['callbackUrl']
            logging.debug('Waiting for asynchronous task to complete')
            interval = 1
            while r.status_code == 202:
                time.sleep(interval)
                r = requests.get(callback, params={'showDetails': 'true'},
                        headers=headers)
                interval *= 2
            info = json.loads(r.text)
            if info['status'] == 'ERROR':
                raise APIError(r, info['error'])
            return json.loads(r.text).get('response')
        elif r.status_code != 200:
            raise APIError(r)
        return json.loads(r.text)

    def _get(self, path, **kw):
        return self._send(requests.get, path, **kw)

    def _post(self, path, **kw):
        return self._send(requests.post, path, **kw)

    def _put(self, path, **kw):
        return self._send(requests.put, path, **kw)

    def _delete(self, path, **kw):
        return self._send(requests.delete, path, **kw)

    def get_auth_info(self, endpoint, username, api_key):
        if endpoint.endswith('/'):
            endpoint = endpoint[:-1]

        data = {'credentials':
                {'username': username, 'key': api_key}}
        r = requests.post('%s/auth' % endpoint, data=json.dumps(data),
                headers={'Content-Type': 'application/json',
                         'Accept': 'application/json'})
        if r.status_code != 200:
            logging.error('Authentication failed')
            sys.exit(1)

        r = json.loads(r.text)
        if 'cloudDNS' not in r['auth']['serviceCatalog']:
            logging.error('cloudDNS service not available.')
            sys.exit(1)

        return(r['auth']['serviceCatalog']['cloudDNS'][0]['publicURL'],
               r['auth']['token']['id'])

    @property
    def domains(self):
        if not self.domains_loaded:
            self._domains_by_name = {}
            self._domains_by_id = {}
            r = self._get('/domains')
            for domain in r['domains']:
                domain = Domain(self, domain)
                self._domains_by_name[domain.name] = domain
                self._domains_by_id[domain.id] = domain
            self.domains_loaded = True
        return self._domains_by_name

    def _unregister_domain(self, domain):
        del self._domains_by_name[domain.name]
        del self._domains_by_id[domain.id]

    def import_domain(self, content, comment=None):
        data = {'domains': [
                {'contentType': 'BIND_9',
                 'contents': content}]}
        if comment:
            data['domains'][0] = comment
        return self._post('/domains/import', data=data)


def load_records(filename):
    records = []
    lineno = 0
    for line in open(filename).readlines():
        lineno += 1
        parts = line.split()
        if len(parts) == 3:
            records.append({'name': parts[0],
                            'ttl': None,
                            'type': parts[1],
                            'data': parts[2]})
        elif len(parts) == 4:
            records.append({'name': parts[0],
                            'ttl': int(parts[1]),
                            'type': parts[2],
                            'data': parts[3]})
        elif not parts:
            continue
        else:
            print >> sys.stderr, 'Syntax error at %s:%d' % (filename, lineno)
            sys.exit(1)
    return records


def list_domains(options, api):
    domains = api.domains.values()
    domains.sort(key=lambda s: s.name)
    for domain in domains:
        print '%s id=%d' % (domain.name, domain.id)


def delete_domain(options, api):
    try:
        domain = api.domains[options.domain]
        domain.delete()
    except KeyError:
        pass


def import_domain(options, api):
    try:
        input = open(options.zone, 'rt').read()
    except IOError as e:
        print >> sys.stderr, 'Error opening zone file: %s' % e.strerror
        sys.exit(1)

    api.import_domain(input, options.comment)


def export_domain(options, api):
    try:
        domain = api.domains[options.domain]
    except KeyError:
        print >> sys.stderr, 'Unknown domain: %s' % options.domain
        return 1
    print domain.export()


def dump_domain(options, api):
    try:
        domain = api.domains[options.domain]
    except KeyError:
        print >> sys.stderr, 'Unknown domain: %s' % options.domain
        return 1
    for record in domain.records.values():
        print '%(name)s\t%(ttl)d\t%(type)s\t%(data)s' % record.__dict__


def sync_domain(options, api):
    new_records = load_records(options.input)
    try:
        domain = api.domains[options.domain]
    except KeyError:
        print >> sys.stderr, 'Unkown domain: %s' % options.domain
        return 1

    key_to_record = dict(((r.name, r.ttl, r.type, r.data), r)
                         for r in domain.records.values())
    to_create = []
    for record in new_records:
        key = (record['name'], record['ttl'], record['type'], record['data'])
        old_record = key_to_record.get(key)
        if old_record is None:
            to_create.append(record)
        else:
            if record.get('ttl') and record['ttl'] and \
                    record['ttl'] != old_record.ttl:
                old_record.modify(ttl=record['ttl'])
            del key_to_record[key]
    if key_to_record:
        logging.debug('Removing %d obsolete records', len(key_to_record))
        ids = [r.id for r in key_to_record.values()]
        domain.delete_records(ids)
    if to_create:
        logging.debug('Adding %d new records', len(to_create))
        domain.add_records(to_create)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--region',
            choices=ENDPOINTS.keys(), default='us',
            help='Select the RackSpace geographic endpoint')
    parser.add_argument('--username', required=True,
            help='RackSpace username')
    parser.add_argument('--api', dest='api_key', required=True,
            help='API Access key')

    subparsers = parser.add_subparsers(title='Available actions')
    sub = subparsers.add_parser('list',
            help='List all known domains')
    sub.set_defaults(func=list_domains)

    sub = subparsers.add_parser('delete',
            help='Delete domain')
    sub.set_defaults(func=delete_domain)
    sub.add_argument('domain', help='Domain to delete')

    sub = subparsers.add_parser('export-zone',
            help='Export domain information in BIND zone format')
    sub.set_defaults(func=export_domain)
    sub.add_argument('domain', help='Domain to export')

    sub = subparsers.add_parser('import-zone',
            help='Import domain information from BIND zone file')
    sub.set_defaults(func=import_domain)
    sub.add_argument('--comment', help='Comment describing domain')
    sub.add_argument('zone', help='Zone file')

    sub = subparsers.add_parser('dump',
            help='Dump domain records')
    sub.set_defaults(func=dump_domain)
    sub.add_argument('domain', help='Domain to dump')

    sub = subparsers.add_parser('sync',
            help='Synchronize domain records')
    sub.set_defaults(func=sync_domain)
    sub.add_argument('domain', help='Domain to sync')
    sub.add_argument('input', help='File with record data')

    options = parser.parse_args()
    api = API(ENDPOINTS[options.region], options.username, options.api_key)
    try:
        sys.exit(options.func(options, api) or 0)
    except APIError as e:
        print >> sys.stderr, e
        sys.exit(2)


if __name__ == '__main__':
    main()

