class TextBaseC(object):

    @staticmethod
    def RawClean(text):
        #case to lower
        #discard non english, non digit character
        #discard multiple spaces

        text= text.lower()
        text = TextBaseC.DiscardNonAlphaNonDigit(text)
        lTerm = [term for term in text.split() if len(term) > 2]
        text = ' '.join(lTerm)
        return text


    @staticmethod
    def Uniq(text):
        vCol = text.lower().split()
        return " ".join(list(set(vCol)))
    @staticmethod
    def DiscardNonAlphaNonDigit(s):
        res = ""
        for c in s:
            if (c.isalpha() | c.isdigit() | (c == " ")):
                res += c        
            else:
                res += " "
        return res
    @staticmethod
    def DiscardStopWord(text):    
        vTerm = text.lower().split(' ')
        vRes = []
        for term in vTerm:
            if (term in hStopWord):
                continue
            vRes.append(term)
        return ' '.join(vRes)


    @staticmethod    
    def DiscardNonAlpha(s):
        res = ""
        for c in s:
            if (c.isalpha() | (c == " ")):
                res += c        
            else:
                res += " "
        return res

    @staticmethod
    def TermMatchFrac(texta,textb):
        lA = TextBaseC.RawClean(texta).split()
        lB = TextBaseC.RawClean(textb).split()
        if (len(lA) == 0) | (len(lB) == 0):
            return 0
        score = 0

        cnt = 0
        for term in lA:
            if term in lB:
                cnt += 1.0
        score += cnt / float(len(lB))
        cnt = 0.0
        for term in lB:
            if term in lA:
                cnt += 1.0
        score += cnt / float(len(lA))
        score /= 2.0
        return score



    @staticmethod    
    def UW(vCol,hTerm,WindowSize=20, AllowOverlap=False):
        #count the un-ordered count of terms in lTerm appear in text
        if type(hTerm) == list:
            hTerm = dict(zip(hTerm,[0]*len(hTerm)))
        if AllowOverlap:
            return TextBaseC.UWOverlap(vCol,hTerm,WindowSize)
        else:
            return TextBaseC.UWNonOverlap(vCol,hTerm,WindowSize)
    @staticmethod
    def UWOverlap(vCol,hTerm,WindowSize):
        #used terms marked as ""
        #O(n) is OK..    
        cnt = 0    
        for st in range(len(vCol)):
            hMid = dict(hTerm)
            for p in range(st,min(st+WindowSize,len(vCol))):
                if vCol[p] in hMid:
                    del hMid[vCol[p]]
                    vCol[p] = ""                             
            if len(hMid) == 0:
                cnt += 1                        
        return cnt

    @staticmethod
    def UWNonOverlap(vCol,hTerm,WindowSize):
        cnt = 0
        st = 0
        while st < len(vCol):
            hMid = dict(hTerm)
            for i in range(st,min(st+WindowSize,len(vCol))):
                if vCol[i] in hMid:
                    del hMid[vCol[i]]
                    if len(hMid) == 0:
                        cnt += 1
                        st = i
                        break
            st += 1      
        return cnt  


    @staticmethod
    def CoordinateMatchNum(TextA,TextB):
        vColA = TextA.split()
        vColB = TextB.split()
        hB = dict(zip(vColB,[0]*len(vColB)))
        cnt = 0
        for term in vColA:
            if term in hB:
                cnt += 1
        return cnt

    @staticmethod
    def TextMinus(TextA,ToDiscardText):
        lA = TextA.lower().split()
        lB = ToDiscardText.lower().split()
        hB = dict(zip(lB,range(len(lB))))

        lA = [term for term in lA if not term in hB]
        return ' '.join(lA)

