def check_authuser(request):
    try:
        authuser = User.objects.get(id=request.session['authuser']['id'])
    except Exception as e:
        authuser = None
    return authuser

def check_sameuser(request, board):
    if board.user.id == check_authuser(request).id:
        sameuser = True
    else :
        sameuser = False
    return sameuser

