import copy
import os
import os.path
from testing import run_yml_test, Test

class TestCommand(object):
    def __init__(self, name):
        self.name = name

    def execute(self, runpath = '.'):
        raise NotImplemented

    def print_commands(self, runpath = '.'):
        raise NotImplemented

    def execute_in_sandbox(self):
        runpath = self.name
        if not os.path.exists(runpath):
            os.mkdir(runpath)
        cwd = os.getcwd()
        os.chdir(runpath)
        self.execute()
        os.chdir(cwd)
        if os.listdir(runpath) == []:
            os.rmdir(runpath)

class YmlTest(TestCommand):
    def __init__(self, name, ymlfile, inputfiles, settings = dict()):
        super(YmlTest, self).__init__(name)
        self.ymlfile = ymlfile
        self.inputfiles = inputfiles
        self.settings = copy.deepcopy(settings)

    def execute(self, runpath = '.'):
        run_yml_test(self.name, self.ymlfile, self.inputfiles, self.settings)

    def print_commands(self, runpath = '.'):
        test = Test(self.ymlfile, self.settings)
        test.print_commands(runpath)

    def set_command_line_options(self, tool_label, options):
        if not 'tools' in self.settings:
            self.settings['tools'] = {}
        settings = self.settings['tools']
        if not tool_label in settings:
            settings[tool_label] = {}
        settings = settings[tool_label]
        if not 'args' in settings:
            settings['args'] = []
        settings['args'] += options

def linha(tam = 42):
    return "-" * tam


def cabecalho(txt):
    print(linha())
    print(txt.center(42))
    print(linha())


def leiaInt(msg):
    while True:
        try:
            n = int(input(msg))
        except(ValueError, TypeError):
            print("\n\033[31m ERRO: Por favor, digite um número inteiro válido. \033[m")
            continue
        except(KeyboardInterrupt):
            print("\n\033[31m Usuário preferiu não digitar esse número. \033[m")
            return 0
        else:
            return n


