def check_exists(File):
    global userAgent, SearchMethod, SleepTime

    Hash = get_hash(File)

    Headers = {
        'User-Agent': userAgent,
    }
    langList = [ 'en', 'pl', 'pt', 'ru', 'hu', 'it', 'br', 'cz', 'de' ]

