            return ({'lang': Language, 'site' : 'thesubdb.com', 'title' : os.path.basename(File)+" (hash)", 'domain': 'thesubdb.com', 'data': {'file': File, 'link': "/?action=download&hash="+Hash+"&language=pl,en,pt,ru,hu,it,br,cz,de"}, 'file': File})
        else:
