from django.shortcuts import render, redirect
from .models import Member, MemberForm, Year, Course, CourseForm, Class, ClassForm, Location
import datetime

def do_year_check():
    now = datetime.datetime.now()
    try:
        y = Year.objects.get(value=now.year)
    except:
        y = Year(value=now.year)
        y.save()

def index(request):
    do_year_check()
    context = {'years':Year.objects.all(),'members':Member.objects.all()}
    try:
        action = request.POST['action']
        if action == 'delete':
            Member.objects.get(pk=request.POST['member_id']).delete()
        elif action == "search":
            if len(request.POST['name']) != 0:
                context['members'] = context['members'].filter(first_name__contains=request.POST['name']).union(context['members'].filter(last_name__contains=request.POST['name']))
            if int(request.POST['membership_year']) != -1:
                context['members'] = context['members'].filter(membership_years__pk=request.POST['membership_year'])
            context['name'] = request.POST['name']
            context['membership_year'] = int(request.POST['membership_year'])
    except KeyError:
        pass
    context['members'] = context['members'].order_by('last_name','first_name')
    return render(request, 'members/index.html', context)

def add(request):
    if request.POST:
        m = MemberForm(request.POST)
        if m.is_valid():
            m.save()
            return redirect('members:index')
        else:
            context = {'form':m, 'add':'add', 'header':'Add New Member'}
        return render(request, 'members/edit.html', context)
    else:
        context = {'form':MemberForm(), 'add':'add', 'header':'Add New Member'}
        return render(request, 'members/edit.html', context)

def edit(request, member_id):
    m = Member.objects.get(pk=member_id)
    if request.POST:
        mf = MemberForm(request.POST, instance=m, prefix="member")
        context = {'header':'Edit Member',
            'form':mf,
            'membership_years':request.POST['membership_years'],
            'courses':Course.objects.all().order_by('name'),
            'classes':Class.objects.all().order_by('year','-semester'),
            'course_list':m.courses_taken.order_by('course__name','year','-semester')}
        action = request.POST['action']
        if action == 'class' and request.POST['class'] != "-1":
            m.courses_taken.add(Class.objects.get(pk=request.POST['class']))
            m.save()
        elif action == "delete":
            m.courses_taken.remove(Class.objects.get(pk=request.POST['class_id']))
            m.save()
        elif action == 'save':
            if mf.is_valid():
                if m.is_valid_membership_years(request.POST['membership_years']):
                    mf.save()
                    m.set_membership_years(request.POST['membership_years'])
                    return redirect('members:index')
                else:
                    context['membership_years_error'] = "Membership years must be a comma seperated list of years."
        return render(request, 'members/edit.html', context)
    else:
        context = {'form':MemberForm(instance=m, prefix='member'),
